import { headers } from "next/headers";
import { claimUrl, originFrom, qrSvg } from "@/lib/qr";

/** A player's QR code. Scanning it opens the email check for their profile. */
export async function QrCode({
  token,
  label,
  className = "",
}: {
  token: string;
  label: string;
  className?: string;
}) {
  const url = claimUrl(originFrom(await headers()), token);
  const svg = await qrSvg(url);
  return (
    <div
      role="img"
      aria-label={label}
      className={`aspect-square [&>svg]:size-full ${className}`}
      // SVG markup generated by the qrcode library from our own URL.
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  );
}
